import React, { useState } from 'react';
import {
  JxForm,
  JxFormField,
  JxInput,
  JxSelect,
  JxSelectOption,
  JxSwitch,
  JxButton,
  JxStack,
  JxLabel,
} from '@jinx-ui/react';

type Language = 'ru' | 'en';

interface ProfileSettings {
  name: string;
  language: Language;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (settings: ProfileSettings) => void;
}

const ProfileSettingsForm: React.FC<ProfileSettingsFormProps> = ({ onSave }) => {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState<Language>('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <JxForm className="jx-p-4" onSubmit={handleSubmit}>
      <JxStack direction="column" gap="var(--jx-space-4)">
        <JxFormField>
          <JxLabel htmlFor="profile-name">Имя</JxLabel>
          <JxInput
            id="profile-name"
            name="name"
            value={name}
            placeholder="Введите имя"
            onChange={(event: React.ChangeEvent<HTMLInputElement>) =>
              setName(event.target.value)
            }
          />
        </JxFormField>

        <JxFormField>
          <JxLabel htmlFor="profile-language">Язык интерфейса</JxLabel>
          <JxSelect
            id="profile-language"
            name="language"
            value={language}
            onChange={(value: string) => setLanguage(value as Language)}
          >
            <JxSelectOption value="ru">Русский</JxSelectOption>
            <JxSelectOption value="en">English</JxSelectOption>
          </JxSelect>
        </JxFormField>

        <JxFormField>
          <JxStack direction="row" align="center" justify="space-between">
            <JxLabel htmlFor="profile-email-notifications">
              Уведомления на почту
            </JxLabel>
            <JxSwitch
              id="profile-email-notifications"
              name="emailNotifications"
              checked={emailNotifications}
              onChange={(checked: boolean) => setEmailNotifications(checked)}
            />
          </JxStack>
        </JxFormField>

        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </JxStack>
    </JxForm>
  );
};

export default ProfileSettingsForm;

